//! 🚩️ Authored checkpoints publish original graph rows, causal events and local cursors under one decision.
use super::*;
use super::publication::OriginalRepinPublicationRoots;
use crate::original_history_branch::{commit::{OriginalCommitMetadata,OriginalCommitMetadataOutput},commit_transition_ids::OriginalCommitMutationIds};
use semio_framework_os_vcs::{Author,Change,Checkpoint,Alternative,ArtifactHistoryKey};
use semio_framework_os_vcs::io::binary::checkpoint_identity::original::repin_alternative::{OriginalAlternativeBirth,OriginalAlternativeInput};
use semio_framework_os_spr::HistoryTransitionCommitView;
use semio_framework_value::{RetainedCloneGrant,RetainedPublicationDecision,FactoryAuthority};
use std::sync::Arc;
/// 🧳️ The original caller owns every partly authored fact until publication or exact cancellation.
pub struct OriginalCheckpointPublication<M>{binding:Option<OriginalSourceBinding>,decoder:(u64,u64),frontier:(usize,u64,u64,[u8;32]),message:ManuallyDrop<Option<String>>,authors:ManuallyDrop<Option<Vec<Author>>>,metadata:Option<Box<OriginalCommitMetadata>>,facts:ManuallyDrop<Option<OriginalCommitMetadataOutput>>,ids:OriginalCommitMutationIds,batch:Option<Box<OriginalHistoryTransitionBatch>>,output:ManuallyDrop<Option<OriginalHistoryTransitionBatchOutput>>,change:ManuallyDrop<Option<Change>>,checkpoint:ManuallyDrop<Option<Checkpoint>>,alternative:ManuallyDrop<Option<Alternative>>,alternative_birth:OriginalAlternativeBirth,alternative_key:Option<ArtifactHistoryKey>,search:Option<ArtifactHistoryKey>,offset:usize,stage:Option<Box<OriginalReplayStage<M>>>,decision:ManuallyDrop<Option<Arc<dyn RetainedPublicationDecision>>>,decision_close:Option<FactoryAuthority>,alternative_staged:bool,cursor_before:[(usize,usize);3],cursor_values:[Option<String>;3],retirement:RetainedCloneClose,phase:u8,published:Option<(u64,[u8;32])>,closing:bool}
fn event(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>)->Result<bool,OriginalTurnFailure>{let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let mut done=None;admit_original_construction(cx,&mut done,construction(d),|_|run(grant).map(|p|((),p)))}
fn pointer(value:Option<&str>)->(usize,usize){value.map_or((0,0),|v|(v.as_ptr()as usize,v.len()))}
impl<M> OriginalCheckpointPublication<M>{
 pub fn capture_demands()->RetirementDemand{RetirementDemand{capacity_bytes:size_of::<Self>(),..fixed(2*size_of::<Self>()+size_of::<Option<String>>()+size_of::<Vec<Author>>())}}
 /// 📏️ Exposes only the fixed original constructor selected by the current semantic phase.
 pub fn next_construction_demands(&self)->Option<RetirementDemand>{if self.closing||self.published.is_some(){return None}match self.phase{0 if self.metadata.is_none()=>Some(OriginalCommitMetadata::birth_demands()),5 if self.batch.is_none()=>Some(OriginalHistoryTransitionBatch::birth_demands()),11 if self.stage.is_none()=>Some(Self::stage_birth_demands()),_=>None}}
 fn stage_birth_demands()->RetirementDemand{RetirementDemand{capacity_bytes:size_of::<OriginalReplayStage<M>>(),..fixed(2*size_of::<OriginalReplayStage<M>>()+size_of::<Change>()+size_of::<Checkpoint>())}}
 pub fn prepared(&self)->bool{self.phase==15&&!self.closing&&self.published.is_none()}
 pub fn published_frontier(&self)->Option<(u64,[u8;32])>{self.published}
 pub fn boxed_release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),..fixed(size_of::<Option<Box<Self>>>())}}
 pub fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.message.is_none()&&self.authors.is_none()&&self.metadata.is_none()&&self.facts.is_none()&&self.ids.terminal_is_empty()&&self.batch.is_none()&&self.output.is_none()&&self.change.is_none()&&self.checkpoint.is_none()&&self.alternative.is_none()&&self.alternative_birth.terminal_is_empty()&&self.stage.is_none()&&self.decision.is_none()&&self.decision_close.is_none()&&!self.alternative_staged&&self.cursor_values.iter().all(Option::is_none)&&self.retirement.is_empty()}
}
impl<M:ToValue+FromValue+Send+Sync+'static> OriginalCheckpointPublication<M>{
 fn validate<P>(&self,store:&ArtifactStore<P,M>,cx:&StepContext<'_>,frontier:bool)->Result<(),ValueError>where P:ToValue+Send+Sync+'static,M:Mutation<P>+OpBinary+OpText{let parts=store.parts_ref();if !self.binding.is_some_and(|b|b.matches(cx))||cx.native_receiving_identity()!=Some(self.decoder)||parts.owners.snapshot_read_leases.identity()!=self.frontier.0||parts.log.envelope.vcs.edits.retained_issuance()!=self.frontier.1{return Err(invalid("checkpoint changed its original caller, decoder or Store issuer"))}if frontier&&(parts.cursor.generation!=self.frontier.2||parts.cursor.content_revision!=self.frontier.3){return Err(invalid("checkpoint changed its original publication frontier"))}Ok(())}
 /// 🎟️ Actual authored owners move once after all fixed source-frame currencies admit their birth.
 pub fn admit<P>(store:&ArtifactStore<P,M>,message:&mut Option<String>,authors:&mut Vec<Author>,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>where P:ToValue+Send+Sync+'static,M:Mutation<P>+OpBinary+OpText{store.ensure_durable_group_idle().map_err(|_|invalid("checkpoint waits for its original durable writer"))?;if store.local_step_pending()||store.parts_ref().log.envelope.open_transaction.is_some(){return Err(invalid("checkpoint waits for its original local writer").into())}let decoder=cx.native_receiving_identity().ok_or_else(||invalid("checkpoint requires its original native decoder"))?;let binding=OriginalSourceBinding::borrow(cx);let parts=store.parts_ref();let frontier=(parts.owners.snapshot_read_leases.identity(),parts.log.envelope.vcs.edits.retained_issuance(),parts.cursor.generation,parts.cursor.content_revision);let d=Self::capture_demands();admit_original_construction(cx,output,construction(d),|_|Ok((Box::new(Self{binding:Some(binding),decoder,frontier,message:ManuallyDrop::new(message.take()),authors:ManuallyDrop::new(Some(std::mem::take(authors))),metadata:None,facts:ManuallyDrop::new(None),ids:Default::default(),batch:None,output:ManuallyDrop::new(None),change:ManuallyDrop::new(None),checkpoint:ManuallyDrop::new(None),alternative:ManuallyDrop::new(None),alternative_birth:Default::default(),alternative_key:None,search:None,offset:0,stage:None,decision:ManuallyDrop::new(None),decision_close:None,alternative_staged:false,cursor_before:[(0,0);3],cursor_values:std::array::from_fn(|_|None),retirement:Default::default(),phase:0,published:None,closing:false}),progress(d))))}
 /// 🪡️ Every source, canonical suffix and local cursor remains private until the final graph decision.
 pub fn advance<P>(&mut self,store:&mut ArtifactStore<P,M>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>where P:ToValue+Send+Sync+'static,M:Mutation<P>+OpBinary+OpText{self.validate(store,cx,true)?;if self.closing||cx.is_cancelled(){return Ok(false)}if self.prepared(){return Ok(true)}match self.phase{
 0=>{if OriginalCommitMetadata::admit(store,&mut self.message,self.authors.as_mut().unwrap(),cx,&mut self.metadata)?{self.phase=1;}},
 1=>{if self.metadata.as_mut().unwrap().advance(store,cx)?{self.phase=2;}},
 2=>{if self.metadata.as_mut().unwrap().take(cx,&mut self.facts)?{self.phase=3;}},
 3=>{let owner=self.metadata.as_mut().unwrap();if !owner.terminal_is_empty(){owner.close_step(cx)?;}else{let d=RetirementDemand{release_bytes:size_of::<OriginalCommitMetadata>(),..fixed(size_of::<Option<Box<OriginalCommitMetadata>>>())};close_original_retained_step(cx,d,|_|{self.metadata=None;self.phase=4;Ok(RetainedCloneStep::Progress(progress(d)))})?;}},
 4=>{if self.ids.advance(store,&self.facts.as_ref().unwrap().change.edit_ids,cx)?{self.phase=5;}},
 5=>{let facts=self.facts.as_ref().unwrap();let view=HistoryTransitionCommitView{checkpoint_id:&facts.checkpoint.id,parent_id:facts.checkpoint.parent_id.as_deref(),change_id:&facts.change.id,mutation_ids:self.ids.values(),description:facts.change.description.as_deref(),saved_at:&facts.change.saved_at,authors:&facts.checkpoint.authors,message:facts.checkpoint.message.as_deref(),timestamp:&facts.checkpoint.timestamp,line_id:store.parts_ref().log.envelope.active_alternative_id.as_deref()};if self.batch.is_none(){OriginalHistoryTransitionBatch::admit_commit(store,&view,cx,&mut self.batch)?;}else if !self.batch.as_ref().unwrap().ready(){self.batch.as_mut().unwrap().advance_commit(store,&view,cx)?;}else if self.batch.as_mut().unwrap().take(cx,&mut self.output)?{self.phase=6;}},
 6=>{let owner=self.batch.as_mut().unwrap();if !owner.terminal_is_empty(){owner.close_step(cx)?;}else{let d=RetirementDemand{release_bytes:size_of::<OriginalHistoryTransitionBatch>(),..fixed(size_of::<Option<Box<OriginalHistoryTransitionBatch>>>())};close_original_retained_step(cx,d,|_|{self.batch=None;self.search=store.parts_ref().log.envelope.vcs.alternatives.last_key();self.phase=7;Ok(RetainedCloneStep::Progress(progress(d)))})?;}},
 7=>{let d=fixed(256);event(cx,d,|_|{let log=store.parts_ref().log;if let Some(target)=log.envelope.active_alternative_id.as_deref(){let key=self.search.ok_or_else(||invalid("checkpoint active alternative has no original canonical row"))?;let row=log.envelope.vcs.alternatives.get_key(key).ok_or_else(||invalid("checkpoint alternative changed"))?;let end=(self.offset+64).min(target.len());if row.id.len()!=target.len()||row.id.as_bytes()[self.offset..end]!=target.as_bytes()[self.offset..end]{self.search=log.envelope.vcs.alternatives.previous_key(key);self.offset=0;}else if end==target.len(){self.alternative_key=Some(key);self.offset=0;self.phase=8;}else{self.offset=end;}}else{self.phase=10;}Ok(progress(d))})?;},
 8=>{let alternative=store.parts_ref().log.envelope.vcs.alternatives.get_key(self.alternative_key.unwrap()).ok_or_else(||invalid("checkpoint original alternative disappeared"))?;let input=OriginalAlternativeInput{generation:self.frontier.2,alternative,checkpoint_id:None,replacement:&self.facts.as_ref().unwrap().checkpoint.id};if self.alternative_birth.ready(){let d=fixed(2*size_of::<Alternative>()+128);event(cx,d,|g|{let Some((value,p))=self.alternative_birth.take(g)?else{return Ok(Default::default())};*self.alternative=Some(value);self.phase=10;Ok(p)})?;}else{let d=self.alternative_birth.demands(&input)?;event(cx,d,|g|self.alternative_birth.advance(&input,g))?;}},
 10=>{let facts=self.facts.as_ref().unwrap();if self.cursor_values[1].is_none(){let d=RetirementDemand{capacity_bytes:facts.current.len(),..fixed(128)};event(cx,d,|_|{let mut value=String::new();value.try_reserve_exact(facts.current.len()).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"checkpoint persisted cursor identity refused"))?;value.push_str(&facts.current);self.cursor_values[1]=Some(value);Ok(progress(d))})?;}else{let d=fixed(2*size_of::<OriginalCommitMetadataOutput>()+2*size_of::<Option<String>>());event(cx,d,|_|{let facts=self.facts.take().unwrap();*self.change=Some(facts.change);*self.checkpoint=Some(facts.checkpoint);self.cursor_values[0]=Some(facts.current);self.phase=11;Ok(progress(d))})?;}},
 11=>{let d=Self::stage_birth_demands();admit_original_construction(cx,&mut self.stage,construction(d),|_|Ok((Box::new(OriginalReplayStage::new_graph_rows(&mut self.change,&mut self.checkpoint,&mut None)),progress(d))))?;if self.stage.is_some(){self.phase=12;}},
 12=>{if self.stage.as_mut().unwrap().advance_graph(store,self.output.as_mut().unwrap(),self.frontier.2,cx)?{self.phase=13;}},
 13 if self.alternative_key.is_some()=>{if self.decision.is_none(){let d=fixed(size_of::<Arc<dyn RetainedPublicationDecision>>());event(cx,d,|_|{*self.decision=Some(self.stage.as_ref().unwrap().graph_decision().unwrap().clone());Ok(progress(d))})?;}else{let key=self.alternative_key.unwrap();let d=store.parts_ref().log.envelope.vcs.alternatives.replacement_stage_demands(key)?;event(cx,d,|g|{let p=store.parts().log.envelope.vcs.alternatives.stage_replacement(key,&mut self.alternative,&mut self.decision,g)?;if self.alternative.is_none(){self.alternative_staged=true;self.phase=14;}Ok(p)})?;}},
 13=>{let d=fixed(1);event(cx,d,|_|{self.phase=14;Ok(progress(d))})?;},
 14=>{let d=fixed(3*size_of::<(usize,usize)>()+1);event(cx,d,|_|{let log=store.parts_ref().log;let cursor=log.envelope.cursor.as_ref().ok_or_else(||invalid("checkpoint requires its original persisted cursor"))?;self.cursor_before=[pointer(log.current_checkpoint_id.as_deref()),pointer(cursor.checkpoint_id.as_deref()),pointer(log.envelope.viewer_checkpoint_id.as_deref())];self.phase=15;Ok(progress(d))})?;},
 _=>return Err(invalid("checkpoint original publication phase changed").into()),
 }Ok(self.prepared())}
 /// 🪟️ Canonical records, original causal pages and local current-head identities publish together.
 pub fn publish<P>(&mut self,store:&mut ArtifactStore<P,M>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>where P:ToValue+Send+Sync+'static,M:Mutation<P>+OpBinary+OpText{self.validate(store,cx,true)?;if !self.prepared(){return Err(invalid("checkpoint is not ready for its original decision").into())}let parts=store.parts_ref();let checkpoints=(parts.log.envelope.vcs.checkpoints.retained_issuance(),0);let alternatives=(parts.log.envelope.vcs.alternatives.retained_issuance(),usize::from(self.alternative_staged));let stage=self.stage.as_mut().unwrap();let d=stage.graph_publication_demands(store,true)?;event(cx,d,|g|{let mut roots=OriginalRepinPublicationRoots{checkpoints,alternatives,cursor_before:self.cursor_before,replace_cursor:[true,true,false],cursor_values:&mut self.cursor_values};let p=stage.publish_graph(store,self.output.as_ref().unwrap(),&mut roots,g)?;if p.copied_items!=0{self.published=Some((store.generation(),store.content_revision()));self.phase=16;}Ok(p)})}
 /// 📐️ Cancellation quotes the actual first pending graph, source or canonical owner.
 pub fn close_demands<P>(&self,store:&ArtifactStore<P,M>,body:usize)->Result<RetirementDemand,ValueError>where P:ToValue+Send+Sync+'static,M:Mutation<P>+OpBinary+OpText{if self.terminal_is_empty(){return Ok(Default::default())}if !self.closing{return Ok(fixed(1))}if self.stage.as_ref().and_then(|s|s.graph_decision()).is_some_and(|v|v.pending()){return self.stage.as_ref().unwrap().close_demands(store,body)}if !self.retirement.is_empty(){return self.retirement.demands(body)}if let Some(owner)=self.decision_close.as_ref(){return if owner.terminal_is_empty(){Ok(fixed(size_of::<Option<FactoryAuthority>>()))}else{owner.demands(body)}}if self.alternative.is_some(){return self.retirement.next_owner_demands::<Alternative>(true,&None,body)}if self.alternative_staged{return store.parts_ref().log.envelope.vcs.alternatives.replacement_settlement_demands(self.alternative_key.unwrap())}if !self.alternative_birth.terminal_is_empty(){return self.alternative_birth.close_demands(body)}
 macro_rules! child{($field:ident,$ty:ty)=>{if let Some(owner)=self.$field.as_ref(){return if owner.terminal_is_empty(){Ok(RetirementDemand{release_bytes:size_of::<$ty>(),..fixed(size_of::<Option<Box<$ty>>>())})}else{owner.close_demands(body)}}};}child!(metadata,OriginalCommitMetadata);child!(batch,OriginalHistoryTransitionBatch);if !self.ids.terminal_is_empty(){return self.ids.close_demands(body)}if let Some(owner)=self.stage.as_ref(){return if owner.terminal_is_empty(){Ok(RetirementDemand{release_bytes:size_of::<OriginalReplayStage<M>>(),..fixed(size_of::<Option<Box<OriginalReplayStage<M>>>>())})}else{owner.close_demands(store,body)}}if self.decision.is_some(){return Ok(fixed(size_of::<Option<Arc<dyn RetainedPublicationDecision>>>()+size_of::<Option<FactoryAuthority>>()))}
 macro_rules! value{($field:ident,$ty:ty)=>{if self.$field.is_some(){return self.retirement.next_owner_demands::<$ty>(true,&None,body)}};}value!(message,String);value!(authors,Vec<Author>);value!(facts,OriginalCommitMetadataOutput);value!(change,Change);value!(checkpoint,Checkpoint);value!(output,OriginalHistoryTransitionBatchOutput);if self.cursor_values.iter().any(Option::is_some){return self.retirement.next_owner_demands::<String>(true,&None,body)}Ok(fixed(size_of::<Option<OriginalSourceBinding>>()))}
 /// ♻️ The common decision aborts before any prepared replacement or original source is returned.
 pub fn close_step<P>(&mut self,store:&mut ArtifactStore<P,M>,body:usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>where P:ToValue+Send+Sync+'static,M:Mutation<P>+OpBinary+OpText{if self.terminal_is_empty(){return Ok(true)}self.validate(store,cx,false)?;let d=self.close_demands(store,body)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(cx.retained_grant(),d){return Ok(false)}if !self.closing{close_original_retained_step(cx,d,|_|{self.closing=true;Ok(RetainedCloneStep::Progress(progress(d)))})?;return Ok(false)}if self.stage.as_ref().and_then(|s|s.graph_decision()).is_some_and(|v|v.pending()){self.stage.as_mut().unwrap().close_step(store,cx)?;return Ok(false)}if !self.retirement.is_empty(){let selection=self.retirement.select(body)?;close_original_retained_step(cx,d,|g|selection.step(g))?;return Ok(false)}if let Some(owner)=self.decision_close.as_mut(){if owner.terminal_is_empty(){close_original_retained_step(cx,d,|_|{self.decision_close=None;Ok(RetainedCloneStep::Progress(progress(d)))})?;}else{close_original_retained_step(cx,d,|g|owner.step(g))?;}return Ok(false)}
 macro_rules! value{($field:ident)=>{if self.$field.is_some(){close_original_retained_step(cx,d,|g|Ok(self.retirement.begin_granted(&mut self.$field,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default()))))?;return Ok(false)}};}value!(alternative);if self.alternative_staged{close_original_retained_step(cx,d,|g|{let p=store.parts().log.envelope.vcs.alternatives.settle_replacement(self.alternative_key.unwrap(),&mut self.alternative,&mut self.decision_close,g)?;if p.copied_items!=0{self.alternative_staged=false;}Ok(RetainedCloneStep::Progress(p))})?;return Ok(false)}if !self.alternative_birth.terminal_is_empty(){close_original_retained_step(cx,d,|g|self.alternative_birth.close_step(body,g))?;return Ok(false)}
 macro_rules! child{($field:ident)=>{if let Some(owner)=self.$field.as_mut(){if owner.terminal_is_empty(){close_original_retained_step(cx,d,|_|{self.$field=None;Ok(RetainedCloneStep::Progress(progress(d)))})?;}else{owner.close_step(cx)?;}return Ok(false)}};}child!(metadata);child!(batch);if !self.ids.terminal_is_empty(){self.ids.close_step(cx)?;return Ok(false)}if let Some(owner)=self.stage.as_mut(){if owner.terminal_is_empty(){close_original_retained_step(cx,d,|_|{self.stage=None;Ok(RetainedCloneStep::Progress(progress(d)))})?;}else{owner.close_step(store,cx)?;}return Ok(false)}if self.decision.is_some(){close_original_retained_step(cx,d,|_|{self.decision_close=Some(self.decision.take().unwrap().into_retirement());Ok(RetainedCloneStep::Progress(progress(d)))})?;return Ok(false)}value!(message);value!(authors);value!(facts);value!(change);value!(checkpoint);value!(output);for value in &mut self.cursor_values{if value.is_some(){close_original_retained_step(cx,d,|g|Ok(self.retirement.begin_granted(value,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default()))))?;return Ok(false)}}close_original_retained_step(cx,d,|_|{self.binding=None;Ok(RetainedCloneStep::Complete(progress(d)))})?;Ok(self.terminal_is_empty())}
}
impl<M> Drop for OriginalCheckpointPublication<M>{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"checkpoint publication requires original custody closure");}}
